def variable_type(vector, boolean_type="numeric"):
    """Determine the kind of data that we're working with."""
    # If a scalar value is passed in, we'll treat it as numeric
    if isinstance(vector, numbers.Number):
        return "numeric"
    if isinstance(vector, (np.bool_, bool)):
        return "boolean" if boolean_type == "boolean" else "numeric"
    if isinstance(vector, pd.Series):
        vector = vector.values

    # Special-case all-na data, which is always "numeric"
    if pd.isna(vector).all():
        return "numeric"

    # Special-case binary/boolean data, allow caller to determine
    # This triggers a numpy warning when vector has strings/objects
    # https://github.com/numpy/numpy/issues/6784
    # Because we reduce with .all(), we are agnostic about whether the
    # comparison returns a scalar or vector, so we will ignore the warning
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", category=FutureWarning)
        if len(np.unique(vector)) == 2 and vector.dtype != object:
            return "boolean" if boolean_type == "boolean" else "numeric"
        elif len(np.unique(vector)) == 2:
            is_bool = np.isin(np.unique(vector), [True, False]).all()
            if is_bool:
                return "boolean" if boolean_type == "boolean" else "numeric"

    # Now that we've made it through the special cases, we can use the
    # pandas type inference
    if np.issubdtype(vector.dtype, np.number):
        return "numeric"
    elif np.issubdtype(vector.dtype, np.datetime64):
        return "datetime"
    elif vector.dtype == object:
        return "categorical"
    else:
        return "unknown"
