def variable_type(vector, boolean_type="numeric"):
    """Determine whether a vector contains numeric or categorical data.

    This function is used to determine the type of data in a vector, which
    is used to determine the appropriate type of plot to draw.

    Parameters
    ----------
    vector : array-like
        The data.
    boolean_type : {'numeric', 'categorical'}
        The type of data to return for a boolean vector.

    Returns
    -------
    type : {'numeric', 'categorical'}
    """
    vector = np.asarray(vector)

    if vector.dtype.kind == "b":
        return boolean_type

    # Special-case all-na data, which is always "numeric"
    if pd.isna(vector).all():
        return "numeric"

    # Special-case binary/boolean data, allow caller to determine
    elif np.unique(vector).size <= 2:
        return "numeric" if vector.dtype.kind == "b" else "categorical"

    # Now test if the data is numeric
    elif np.issubdtype(vector.dtype, np.number):
        return "numeric"

    # If the data is not numeric, it must be categorical
    else:
        return "categorical"
