    elif np.issubdtype(dtype, np.datetime64):
        return dtype, np.datetime64("NaT")
    elif np.issubdtype(dtype, np.integer):
        return np.float64, np.nan
    elif np.issubdtype(dtype, np.bool_):
        return np.object_, np.nan
    return np.object_, np.nan
